1st Question  
Prefix XOR 
Given an Array where each element is XOR of all the previous elements in original array, return the original 
array. 

Now I don’t remember their sample examples but solution was somewhat similar to this 
vector<int> helper(vector<int> pref) 
{ 
    int n = pref.size(); 
    vector<int> ans(n); 
    ans[0] = pref[0]; 

    for (int i = 1; i < n; i++) 
    { 
        ans[i]=pref[i]^pref[i-1]; 
    } 

    return ans; 
} 


Solution: 

a) A^ B = B ^ A 
b) A ^ A = 0 
c) A ^ 0 = A 

pref[i] = arr [i] ^ arr[i - 1] ^ … arr [0] 
pref[i] = arr [i] ^ pref[i – 1] 
pref[i] ^ pref[i – 1] = arr [i] ^ pref[i – 1] ^ pref[i – 1] 
pref[i] ^ pref[i – 1] = arr [i] ^ 0 
arr[i] = pref[i] ^ pref[i - 1] 

